import cv2, numpy as np
F=np.load('source_pixels.npz')['rgb']
for i,im in enumerate(F):
 r,g,b=im[:,:,0],im[:,:,1],im[:,:,2]
 m=((r>140)&(r>g*1.5)&(r>b*1.3)&(g<135)&(np.indices(r.shape)[0]<60)).astype('uint8')
 n,l,st,cen=cv2.connectedComponentsWithStats(m,8)
 cs=[]
 for k in range(1,n):
  x,y,w,h,a=st[k];
  if a>=2: cs.append((a,round(cen[k][0],1),round(cen[k][1],1),(x,y,w,h)))
 if i<55: print(f'{i+1:02}',sorted(cs,reverse=True)[:6])
PY"
